#pragma once
#include "core/display_setup.hpp"
#include "core/startup_display_contracts.hpp"
#include <array>
namespace rolo {
enum class ScreenAssetOperation{FillBytes,FillNames,Transfer,Rectangle,ControlWord,ControlLong,DataLong,InitializeStorage,InitializeDisplay,InitializeSound,CopyRenderer,ResetWordQueue,ResetByteQueue,ResidentGraphics,ResetInput,PlaneDimensions,InitializeRegion,Music};
struct ScreenAssetRequest{ScreenAssetOperation operation;std::uint32_t a{},b{},c{},d{},e{};bool operator==(const ScreenAssetRequest&)const=default;};
struct ScreenAssetState{std::uint32_t next{},main_state{};std::uint16_t pattern{},display{},status{},random{};std::uint8_t complete{},credits{};};
struct ScreenAssetServices{virtual ~ScreenAssetServices()=default;virtual std::uint32_t decode(std::uint32_t)=0;virtual void request(ScreenAssetRequest)=0;virtual void text(std::uint32_t,std::uint16_t,std::uint16_t,std::uint16_t)=0;virtual void append_text(std::uint32_t)=0;virtual void version_text(std::array<std::uint8_t,3>,std::uint16_t,std::uint16_t,std::uint16_t)=0;};
inline void screen_decode_upload(ScreenAssetState&s,std::uint32_t source,ScreenAssetServices&v){const auto size=v.decode(source);const auto destination=s.next;s.next+=size;auto words=std::uint16_t(size);words=std::uint16_t((words>>1)|(words&0x8000));v.request({ScreenAssetOperation::Transfer,0xffff0000,destination,0x40000000,words});}
inline void initialize_game_over_art(ScreenAssetState&s,ScreenAssetServices&v){v.request({ScreenAssetOperation::FillBytes,0x1111,32,31,0x40000000});v.request({ScreenAssetOperation::FillNames,0xc001,0xe000,0x540,0x40000000});s.next=0x2ee0;screen_decode_upload(s,0x474d4,v);(void)v.decode(0x49434);v.request({ScreenAssetOperation::Rectangle,0xffff0000,0xe08c,0x8177,26,18});v.request({ScreenAssetOperation::ControlWord,0x8f02});v.request({ScreenAssetOperation::ControlLong,0x70000003});v.request({ScreenAssetOperation::DataLong,8});}
inline void initialize_title_art(ScreenAssetState&s,ScreenAssetServices&v){s.next=0x1540;screen_decode_upload(s,0x28a80,v);if(!s.complete)v.request({ScreenAssetOperation::Rectangle,0x4592c,0xc000,std::uint16_t((s.next>>5)|0xe000),39,5});screen_decode_upload(s,0x44f1c,v);v.request({ScreenAssetOperation::Rectangle,0x2b680,0xe300,0xaa,39,13});v.request({ScreenAssetOperation::Rectangle,0x2bae0,0xc300,0x80aa,39,13});v.request({ScreenAssetOperation::Rectangle,0x4a64a,0xea02,0x206a,7,7});v.request({ScreenAssetOperation::Rectangle,0x4a64a,0xea3e,0x206a,7,7});s.pattern=std::uint16_t(s.next>>5);}
inline void initialize_continue_art(ScreenAssetState&s,std::span<const std::uint8_t>positions,ScreenAssetServices&v){if(s.credits>4||positions.size()<5)throw std::out_of_range("Continue credit selector domain");s.random=3;if(s.credits)v.text(0x13c57,13,4,0x6000);const auto old=s.credits;s.credits=std::uint8_t(old-1);v.text(0x13bfc+std::uint32_t(old)*16,positions[old],23,0x6000);v.append_text(0x13c4c);const auto size=v.decode(0x40000);s.pattern=std::uint16_t((size>>5)+1);v.request({ScreenAssetOperation::Transfer,0xffff0000,32,0x40000000,size});v.request({ScreenAssetOperation::Rectangle,0x4045c,0xc380,1,39,13});}
inline void publish_region_diagnostics(std::uint8_t version,ScreenAssetServices&v){v.text(0x5828,0,22,0x6000);v.text((version&128)?0x585c:0x5866,13,22,0x6000);v.text(0x5835,0,23,0x6000);v.text((version&64)?0x5870:0x5880,13,23,0x6000);v.text(0x5842,0,24,0x6000);v.text((version&32)?0x589c:0x5891,13,24,0x6000);v.text(0x584f,0,25,0x6000);const auto revision=version&15;v.version_text({std::uint8_t(48+revision/10),std::uint8_t(48+revision%10),0},13,25,0x6000);v.text(0x58ab,0,27,0x6000);}
inline void initialize_main_subsystems(ScreenAssetState&s,ScreenAssetServices&v){for(auto op:{ScreenAssetOperation::InitializeStorage,ScreenAssetOperation::InitializeDisplay,ScreenAssetOperation::InitializeSound})v.request({op});s.display|=32;v.request({ScreenAssetOperation::ControlWord,s.display});for(auto op:{ScreenAssetOperation::CopyRenderer,ScreenAssetOperation::ResetWordQueue,ScreenAssetOperation::ResetByteQueue,ScreenAssetOperation::ResidentGraphics,ScreenAssetOperation::ResetInput})v.request({op});s.main_state=0x165e;v.request({ScreenAssetOperation::PlaneDimensions,64,32});v.request({ScreenAssetOperation::InitializeRegion});s.status=0x2500;s.display|=64;v.request({ScreenAssetOperation::ControlWord,s.display});v.request({ScreenAssetOperation::Music});}
}
